// Classify each requirement and detect the driving tradeoff.
// A requirement is non-functional if it names a number/quality:
//   rps, latency, availability, durability, consistency.
// Tension rule: if there is a latency requirement <= 100ms AND a durability
// requirement, flag "low-latency reads vs durable writes".
const spec = {
  requirements: [
    { id: "shorten", kind: "does: create short code" },
    { id: "redirect", kind: "does: resolve short code" },
    { id: "p99", quality: "latency", value: 50 },
    { id: "uptime", quality: "availability", value: "99.99%" },
    { id: "counts", quality: "durability", value: "survive crash" },
  ],
};
function analyze(s) {
  const functional = [];
  const nonFunctional = [];
  let fastReads = false;
  let durableWrites = false;
  for (const requirement of s.requirements) {
    if (requirement.kind) functional.push(requirement.id);
    else nonFunctional.push(requirement.id);
    if (requirement.quality === "latency" && typeof requirement.value === "number" && requirement.value <= 100) fastReads = true;
    if (requirement.quality === "durability") durableWrites = true;
  }
  return {
    functional,
    nonFunctional,
    tradeoff: fastReads && durableWrites ? "low-latency reads vs durable writes" : "none",
  };
}
const r = analyze(spec);
console.log("functional:", r.functional.join(","));
console.log("nonFunctional:", r.nonFunctional.join(","));
console.log("tradeoff:", r.tradeoff);

