class LruCache {
  constructor(cap) { this.cap = cap; this.map = new Map(); this.hits = 0; this.misses = 0; }
  get(key) {
    if (!this.map.has(key)) { this.misses++; return undefined; }
    const v = this.map.get(key); this.map.delete(key); this.map.set(key, v); this.hits++; return v;
  }
  put(key, val) {
    if (this.map.has(key)) this.map.delete(key);
    else if (this.map.size >= this.cap) this.map.delete(this.map.keys().next().value);
    this.map.set(key, val);
  }
  hitRate() { const t = this.hits + this.misses; return t ? this.hits / t : 0; }
}
function runTrace(cap, trace) {
  const c = new LruCache(cap);
  for (const k of trace) { if (c.get(k) === undefined) c.put(k, k); }
  return c.hitRate();
}
const trace = ["A", "B", "C", "A", "B", "C", "A", "B", "C"];
