class Coalescer {
  constructor() { this.inflight = new Map(); this.computes = 0; }
  async run(key, compute) {
    if (this.inflight.has(key)) return this.inflight.get(key);
    const task = (async () => { this.computes++; return await compute(); })();
    this.inflight.set(key, task);
    try { return await task; } finally { this.inflight.delete(key); }
  }
}
