class WeightedLB {
  constructor(backends) {
    this.backends = backends.map(b => ({ id: b.id, weight: b.weight, healthy: b.healthy !== false, current: 0 }));
  }
  healthyPool() { return this.backends.filter(b => b.healthy); }
  next() {
    const pool = this.healthyPool();
    const total = pool.reduce((s, b) => s + b.weight, 0);
    for (const b of pool) b.current += b.weight;
    let best = pool[0];
    for (const b of pool) if (b.current > best.current) best = b;
    best.current -= total;
    return best;
  }
}
const lb = new WeightedLB([
  { id: "big", weight: 3 },
  { id: "small", weight: 1 },
  { id: "down", weight: 5, healthy: false },
]);
