class BoundedDedupConsumer {
  constructor(capacity) { this.capacity = capacity; this.seen = []; this.effects = 0; }
  handle(msg) {
    if (this.seen.includes(msg.id)) return "skipped-duplicate";
    this.effects++;
    this.seen.push(msg.id);
    if (this.seen.length > this.capacity) this.seen.shift();
    return "processed";
  }
}
