function radius(dependents, failed) {
  const down = new Set([failed]);
  const stack = [failed];
  while (stack.length) {
    const node = stack.pop();
    for (const dep of (dependents[node] || [])) if (!down.has(dep)) { down.add(dep); stack.push(dep); }
  }
  return down.size;
}
function worstSpof(dependents) {
  const nodes = Object.keys(dependents);
  return nodes
    .map(n => ({ node: n, blast: radius(dependents, n) }))
    .sort((a, b) => b.blast - a.blast || a.node.localeCompare(b.node));
}
