class CircuitBreakerK {
  constructor(failThreshold, cooldownMs, successThreshold) {
    this.state = "closed"; this.failures = 0; this.successes = 0;
    this.failThreshold = failThreshold; this.cooldownMs = cooldownMs;
    this.successThreshold = successThreshold; this.openedAt = 0;
  }
  onResult(ok, now) {
    if (this.state === "open" && now - this.openedAt >= this.cooldownMs) { this.state = "half-open"; this.successes = 0; }
    if (this.state === "half-open") {
      if (ok) {
        this.successes++;
        if (this.successes >= this.successThreshold) { this.state = "closed"; this.failures = 0; }
      } else { this.state = "open"; this.openedAt = now; }
      return this.state;
    }
    if (ok) this.failures = 0;
    else if (++this.failures >= this.failThreshold) { this.state = "open"; this.openedAt = now; }
    return this.state;
  }
}
