class PriorityLimiter {
  constructor(capacity, refillPerSec, reservedForHigh) {
    this.capacity = capacity; this.tokens = capacity; this.refillPerSec = refillPerSec;
    this.reserved = reservedForHigh; this.last = 0;
  }
  tryAdmit(priority, now) {
    const elapsed = now - this.last; this.last = now;
    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillPerSec);
    const floor = priority === "high" ? 0 : this.reserved;
    if (this.tokens - 1 >= floor) { this.tokens -= 1; return true; }
    return false;
  }
}
