const B62 = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
function toCode(n) { let s = ""; do { s = B62[n % 62] + s; n = Math.floor(n / 62); } while (n > 0); return s; }
function pickShard(code, shardCount) { let h = 0; for (const c of code) h = (h * 31 + c.charCodeAt(0)) >>> 0; return h % shardCount; }
class Shortener {
  constructor(shardCount, limiterCapacity) {
    this.shardCount = shardCount;
    this.shards = Array.from({ length: shardCount }, () => new Map());
    this.cache = new Map();
    this.tokens = limiterCapacity; this.nextId = 1;
  }
  create(url) {
    if (this.tokens < 1) return null;
    this.tokens -= 1;
    const code = toCode(this.nextId++);
    const shard = pickShard(code, this.shardCount);
    this.shards[shard].set(code, url);
    this.cache.set(code, url);
    return code;
  }
  resolve(code) {
    if (this.cache.has(code)) return this.cache.get(code);
    return this.shards[pickShard(code, this.shardCount)].get(code);
  }
}
const s = new Shortener(3, 5);
const urls = ["a", "b", "c", "d", "e", "f", "g"];
const codes = urls.map(u => s.create(u));
const created = codes.filter(c => c !== null);
const rejected = codes.filter(c => c === null).length;
const unique = new Set(created).size === created.length;
const noDangling = [...s.cache.keys()].every(c => s.resolve(c) !== undefined && s.shards[pickShard(c, 3)].has(c));
const perShard = Array.from({ length: 3 }, (_, i) => s.shards[i].size).join(",");
console.log("created:", created.length, "rejected:", rejected);
console.log("uniqueCodes:", unique);
